return class extends DCLogic {
  renderVals() {
    const picked = this.state.p;
    const opts = [{"id": 0, "t": "Keep coming straight in"}, {"id": 1, "t": "Join the lap behind the 152"}, {"id": 2, "t": "Call the 152 and agree who goes first"}].map(o => Object.assign({}, o, {
      st: 'min-height: 56px; padding: 12px 16px; display: flex; align-items: center; border-radius: 14px; font-size: 16px; font-weight: 600; cursor: pointer; box-sizing: border-box; background: ' + (o.id === picked ? '#F6EFE4' : '#FFFFFF') + '; border: 2px solid ' + (o.id === picked ? '#111111' : '#EAEAE7'),
      pick: () => this.setState({ p: o.id, open: true })
    }));
    return { opts, open: !!this.state.open, closeSheet: () => this.setState({ open: false }), reopen: () => this.setState({ open: true }), done: picked != null };
  }
